result:
**The bug:** The condition `decoded.exp < Date.now() / 1000` uses strict less-than, so when `exp === now` exactly, the token passes. It should be `<=`.

**Deeper issue:** `jwt.verify()` already checks expiry and throws `JsonWebTokenError` / `TokenExpiredError` automatically — the manual check is redundant and the catch block swallows both errors identically, hiding useful information.

Here's the fixed version:

```javascript
const jwt = require('jsonwebtoken');

function authMiddleware(req, res, next) {
  const token = req.headers.authorization?.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'No token provided' });
  }

  if (!process.env.JWT_SECRET) {
    return res.status(500).json({ error: 'Server misconfiguration' });
  }

  try {
    // jwt.verify handles expiry (including exp === now) via clockTolerance: 0
    const decoded = jwt.verify(token, process.env.JWT_SECRET, {
      clockTolerance: 0, // reject tokens expiring at exactly current time
    });

    req.user = decoded;
    next();
  } catch (err) {
    if (err.name === 'TokenExpiredError') {
      return res.status(401).json({ error: 'Token expired' });
    }
    if (err.name === 'JsonWebTokenError') {
      return res.status(401).json({ error: 'Invalid token' });
    }
    // Unexpected error (e.g. key fetch failure) — don't leak details
    res.status(500).json({ error: 'Authentication error' });
  }
}

module.exports = authMiddleware;
```

**Key changes:**

| # | Change | Why |
|---|--------|-----|
| 1 | Removed manual `exp` check | `jwt.verify` already enforces expiry correctly |
| 2 | Added `clockTolerance: 0` | Explicitly rejects `exp === now`; jsonwebtoken's default allows a small skew |
| 3 | Differentiated catch branches | `TokenExpiredError` vs `JsonWebTokenError` gives clients actionable responses (e.g. "refresh" vs "re-login") |
| 4 | Guard on missing `JWT_SECRET` | Prevents a silent `undefined` secret accepting any token |
